package com.nazril.asisten;

import android.webkit.JavascriptInterface;
import android.app.Activity;
import android.content.ActivityNotFoundException;
import android.content.Intent;
import android.media.projection.MediaProjectionManager;
import android.net.Uri;
import android.os.Build;
import android.os.Bundle;
import android.webkit.JavascriptInterface;
import android.webkit.ValueCallback;
import android.webkit.WebChromeClient;
import android.webkit.WebResourceRequest;
import android.webkit.WebResourceResponse;
import android.webkit.WebSettings;
import android.webkit.WebView;
import android.webkit.WebViewClient;

import androidx.webkit.WebViewAssetLoader;

public class MainActivity extends Activity {

    private static final int REQ_FILE_CHOOSER = 1;
        private static final int REQ_SCREEN_CAPTURE = 1001;

            private WebView w;
                private ValueCallback<Uri[]> cb;
                    private WebViewAssetLoader loader;
                        private MediaProjectionManager projectionManager;

                            @Override
                                protected void onCreate(Bundle b) {
                                        super.onCreate(b);

                                                loader = new WebViewAssetLoader.Builder()
                                                                .addPathHandler("/assets/", new WebViewAssetLoader.AssetsPathHandler(this))
                                                                                .build();

                                                                                        w = new WebView(this);
                                                                                                setContentView(w);

                                                                                                        WebSettings s = w.getSettings();
                                                                                                                s.setJavaScriptEnabled(true);
                                                                                                                        s.setDomStorageEnabled(true);

                                                                                                                                // Jembatan agar JavaScript bisa memanggil Android.startScreenCapture()
                                                                                                                                        w.addJavascriptInterface(this, "Android");

                                                                                                                                                w.setWebViewClient(new WebViewClient() {
                                                                                                                                                            @Override
                                                                                                                                                                        public WebResourceResponse shouldInterceptRequest(WebView v, WebResourceRequest r) {
                                                                                                                                                                                        return loader.shouldInterceptRequest(r.getUrl());
                                                                                                                                                                                                    }
                                                                                                                                                                                                            });

                                                                                                                                                                                                                    w.setWebChromeClient(new WebChromeClient() {
                                                                                                                                                                                                                     @Override
                                                                                                                                                                                                                     public void onPermissionRequest(final android.webkit.PermissionRequest request) {
                                                                                                                                                                                                                         runOnUiThread(() -> request.grant(request.getResources()));
                                                                                                                                                                                                                         }   
                                                                                                                                                                                                                                @Override
                                                                                                                                                                                                                                            public boolean onShowFileChooser(WebView v, ValueCallback<Uri[]> c,
                                                                                                                                                                                                                                                                                         FileChooserParams p) {
                                                                                                                                                                                                                                                                                                         if (cb != null) cb.onReceiveValue(null);
                                                                                                                                                                                                                                                                                                                         cb = c;
                                                                                                                                                                                                                                                                                                                                         try {
                                                                                                                                                                                                                                                                                                                                                             startActivityForResult(p.createIntent(), REQ_FILE_CHOOSER);
                                                                                                                                                                                                                                                                                                                                                                             } catch (ActivityNotFoundException e) {
                                                                                                                                                                                                                                                                                                                                                                                                 cb = null;
                                                                                                                                                                                                                                                                                                                                                                                                                     return false;
                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                     return true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                         });

                                                                                                                                                                                                                                                                                                                                                                                                     if (checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)
                                                                                                                                                                                                                                                                                                                                                                                                        != android.content.pm.PackageManager.PERMISSION_GRANTED) {
                                                                                                                                                                                                                                                                                                                                                                                                            requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO}, 77);
                                                                                                                                                                                                                                                                                                                                                                                                            }                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 w.addJavascriptInterface(new NikoBridge(), "NikoNative");
        w.loadUrl("https://appassets.androidplatform.net/assets/index.html");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         class NikoBridge {
        @JavascriptInterface
        public void startBg() {
            runOnUiThread(() -> { try {
                Intent i = new Intent(MainActivity.this, VoiceService.class);
                if (android.os.Build.VERSION.SDK_INT >= 26) startForegroundService(i); else startService(i);
            } catch (Exception e) {} });
        }
        @JavascriptInterface
        public void stopBg() { runOnUiThread(() -> stopService(new Intent(MainActivity.this, VoiceService.class))); }
        @JavascriptInterface
        public void openAccess() { runOnUiThread(() -> startActivity(new Intent(android.provider.Settings.ACTION_ACCESSIBILITY_SETTINGS))); }
        @JavascriptInterface
        public void openBattery() { runOnUiThread(() -> startActivity(new Intent(android.provider.Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS))); }

        android.speech.SpeechRecognizer sr;
        void js(final String s) {
            w.post(() -> w.evaluateJavascript("try{window." + s + "}catch(e){}", null));
        }
        @JavascriptInterface
        public void listen(final String lang) {
            runOnUiThread(() -> {
                try {
                    if (!android.speech.SpeechRecognizer.isRecognitionAvailable(MainActivity.this)) {
                        js("onNikoError('tidak tersedia')");
                        return;
                    }
                    if (sr != null) sr.destroy();
                    sr = android.speech.SpeechRecognizer.createSpeechRecognizer(MainActivity.this);
                    sr.setRecognitionListener(new android.speech.RecognitionListener() {
                        public void onReadyForSpeech(android.os.Bundle b) { js("onNikoState('listen')"); }
                        public void onBeginningOfSpeech() {}
                        public void onRmsChanged(float v) {}
                        public void onBufferReceived(byte[] b) {}
                        public void onEndOfSpeech() {}
                        public void onError(int e) { js("onNikoError('" + e + "')"); }
                        public void onResults(android.os.Bundle b) {
                            java.util.ArrayList<String> l = b.getStringArrayList(android.speech.SpeechRecognizer.RESULTS_RECOGNITION);
                            if (l != null && !l.isEmpty()) js("onNikoResult(" + org.json.JSONObject.quote(l.get(0)) + ")");
                            else js("onNikoError('7')");
                        }
                        public void onPartialResults(android.os.Bundle b) {}
                        public void onEvent(int t, android.os.Bundle b) {}
                    });
                    Intent i = new Intent(android.speech.RecognizerIntent.ACTION_RECOGNIZE_SPEECH);
                    i.putExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE_MODEL, android.speech.RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);
                    i.putExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE, lang);
                    sr.startListening(i);
                } catch (Exception e) {
                    js("onNikoError('tidak tersedia')");
                }
            });
        }
        @JavascriptInterface
        public void stop() {
            runOnUiThread(() -> { if (sr != null) { sr.destroy(); sr = null; } });
        }
    }

    // Dipanggil dari JavaScript: Android.startScreenCapture()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             @JavascriptInterface
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 public void startScreenCapture() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         runOnUiThread(() -> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     projectionManager = (MediaProjectionManager)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         getSystemService(MEDIA_PROJECTION_SERVICE);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     startActivityForResult(projectionManager.createScreenCaptureIntent(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         REQ_SCREEN_CAPTURE);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
@JavascriptInterface
public void saveKey(String k) {
  getSharedPreferences("p", MODE_PRIVATE).edit()
      .putString("key", k == null ? "" : k.trim()).apply();
      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         @Override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             protected void onActivityResult(int rc, int res, Intent d) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     super.onActivityResult(rc, res, d);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             if (rc == REQ_FILE_CHOOSER) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (cb != null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         cb.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(res, d));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         cb = null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 if (rc == REQ_SCREEN_CAPTURE) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             if (res == RESULT_OK && d != null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             Intent svc = new Intent(this, AssistService.class);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             svc.putExtra("resultCode", res);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             svc.putExtra("data", d);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             if (Build.VERSION.SDK_INT >= 26) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 startForegroundService(svc);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     startService(svc);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 w.evaluateJavascript("onScreenCaptureDenied()", null);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             @Override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 public void onBackPressed() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (w.canGoBack()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     w.goBack();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         super.onBackPressed();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }